-- 03-payment.sql
-- 本地 prod-split 真实演示 seed，仅供联调，不属于生产迁移。
-- target database: omni_payment


BEGIN;
-- 支付与退款演示：包含退款异常、UNKNOWN 原始响应。
DELETE FROM refund_request WHERE order_id BETWEEN 980001 AND 980999;
DELETE FROM payment WHERE order_id BETWEEN 980001 AND 980999;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, amount = EXCLUDED.amount;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, review_note = EXCLUDED.review_note, raw_response = EXCLUDED.raw_response;

SELECT setval('payment_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM payment), 1), 1), true);
SELECT setval('refund_request_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM refund_request), 1), 1), true);
COMMIT;
